# shellcheck shell=sh
# Claude Code checks for check.sh (sourced with "." by check.sh, in the same package folder;
# it does not run on its own). Defines check_agent(), which uses check.sh's add, here and
# jq_path.
# ids: agent-cli, agent-auth, plugin, plugin-current. Reads "claude plugin list --json" with jq,
# only if there is jq.
# Strings: the block below appends the table of the agentcheck. area to check.sh's, in its
# language.

# >>> strings (area agentcheck.): generated by tools/script-strings.sh from agents/claude-code/i18n/*.json; do not edit by hand
# shellcheck disable=SC2154 # language and MSG_TABLE come from the script that reads this file
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) msg_joined_table='agentcheck.loginOk	x-test:agentcheck.loginOk
agentcheck.loginOkMethod	x-test:agentcheck.loginOkMethod {0}
agentcheck.noLogin	x-test:agentcheck.noLogin
agentcheck.authUnreadable	x-test:agentcheck.authUnreadable
agentcheck.noCli	x-test:agentcheck.noCli
agentcheck.noCliLogin	x-test:agentcheck.noCliLogin
agentcheck.noCliPlugin	x-test:agentcheck.noCliPlugin {0}
agentcheck.noCliVersions	x-test:agentcheck.noCliVersions
agentcheck.noJqList	x-test:agentcheck.noJqList
agentcheck.noJqVersions	x-test:agentcheck.noJqVersions
agentcheck.listUnreadable	x-test:agentcheck.listUnreadable
agentcheck.noListVersions	x-test:agentcheck.noListVersions
agentcheck.notInstalled	x-test:agentcheck.notInstalled {0} {0} {0}
agentcheck.pluginNotInstalled	x-test:agentcheck.pluginNotInstalled
agentcheck.disabled	x-test:agentcheck.disabled {0} {1} {0} {0}
agentcheck.remoteSource	x-test:agentcheck.remoteSource {0} {1} {1} {1}
agentcheck.folderDiffers	x-test:agentcheck.folderDiffers {0} {1} {2} {2}
agentcheck.same	x-test:agentcheck.same {0}
agentcheck.sameCache	x-test:agentcheck.sameCache {0}
agentcheck.cacheDiffers	x-test:agentcheck.cacheDiffers {0} {1} {1} {2} {1} {1} {2}
agentcheck.sameNotCompared	x-test:agentcheck.sameNotCompared {0}
' ;;
  pt-BR) msg_joined_table='agentcheck.loginOk	com login
agentcheck.loginOkMethod	com login ({0})
agentcheck.noLogin	o CLI claude está sem login; uma sessão nova (a de um trabalhador, a de um teste isolado) para no pedido de login. Entre com: claude auth login (ou /login numa sessão do claude)
agentcheck.authUnreadable	claude auth status --json não deu uma resposta legível; esta versão do CLI pode não ter o comando
agentcheck.noCli	CLI claude não está no PATH; sem ele não há como conferir o plugin. Instale o Claude Code: https://claude.com/claude-code
agentcheck.noCliLogin	sem o CLI claude, não há como saber se há login
agentcheck.noCliPlugin	sem o CLI claude, não há como saber se o plugin {0} está instalado
agentcheck.noCliVersions	sem o CLI claude, não há como comparar versões
agentcheck.noJqList	sem jq, não há como ler a lista de plugins do claude
agentcheck.noJqVersions	sem jq, não há como comparar versões
agentcheck.listUnreadable	claude plugin list --json não devolveu uma lista legível
agentcheck.noListVersions	sem a lista de plugins, não há como comparar versões
agentcheck.notInstalled	plugin {0} não está instalado. Instale: claude plugin marketplace add <origem> e claude plugin install {0}@{0}
agentcheck.pluginNotInstalled	plugin não instalado
agentcheck.disabled	plugin {0} {1} instalado, mas desativado. Ative: claude plugin enable {0}@{0}
agentcheck.remoteSource	versão instalada {0}; a origem não é uma pasta local (é um repositório git, por exemplo), e saber se está em dia exigiria rede. Para atualizar: claude plugin marketplace update {1} e claude plugin update {1}@{1}
agentcheck.folderDiffers	instalada {0}, a pasta de origem tem {1}. Atualize: claude plugin update {2}@{2}
agentcheck.same	{0}, igual à pasta de origem
agentcheck.sameCache	{0}, igual à pasta de origem; a cópia do cache também
agentcheck.cacheDiffers	a cópia do cache ({0}) difere da pasta de origem; a Agents window lê a cópia. Reinstale: claude plugin uninstall {1}@{1} --scope {2} e claude plugin install {1}@{1} --scope {2}
agentcheck.sameNotCompared	{0}, igual à pasta de origem (sem find, sort ou cmp, a cópia do cache não foi comparada)
' ;;
  *) msg_joined_table='agentcheck.loginOk	logged in
agentcheck.loginOkMethod	logged in ({0})
agentcheck.noLogin	the claude CLI is not logged in; a new session (a worker'\''s, an isolated test'\''s) stops at the login prompt. Log in with: claude auth login (or /login in a claude session)
agentcheck.authUnreadable	claude auth status --json gave no readable answer; this CLI version may not have the command
agentcheck.noCli	the claude CLI is not on the PATH; without it there is no way to check the plugin. Install Claude Code: https://claude.com/claude-code
agentcheck.noCliLogin	without the claude CLI, there is no way to know whether you are logged in
agentcheck.noCliPlugin	without the claude CLI, there is no way to know whether the {0} plugin is installed
agentcheck.noCliVersions	without the claude CLI, there is no way to compare versions
agentcheck.noJqList	without jq, there is no way to read the claude plugin list
agentcheck.noJqVersions	without jq, there is no way to compare versions
agentcheck.listUnreadable	claude plugin list --json did not return a readable list
agentcheck.noListVersions	without the plugin list, there is no way to compare versions
agentcheck.notInstalled	the {0} plugin is not installed. Install: claude plugin marketplace add <source> and claude plugin install {0}@{0}
agentcheck.pluginNotInstalled	plugin not installed
agentcheck.disabled	plugin {0} {1} installed, but disabled. Enable: claude plugin enable {0}@{0}
agentcheck.remoteSource	installed version {0}; the source is not a local folder (a git repository, for example), and knowing whether it is current would need the network. To update: claude plugin marketplace update {1} and claude plugin update {1}@{1}
agentcheck.folderDiffers	installed {0}, the source folder has {1}. Update: claude plugin update {2}@{2}
agentcheck.same	{0}, same as the source folder
agentcheck.sameCache	{0}, same as the source folder; so is the cache copy
agentcheck.cacheDiffers	the cache copy ({0}) differs from the source folder; the Agents window reads the copy. Reinstall: claude plugin uninstall {1}@{1} --scope {2} and claude plugin install {1}@{1} --scope {2}
agentcheck.sameNotCompared	{0}, same as the source folder (without find, sort or cmp, the cache copy was not compared)
' ;;
esac
MSG_TABLE="$MSG_TABLE
$msg_joined_table"
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
# <<< strings

# agent-auth: "claude auth status --json" reads the local credential, without network. Only
# loggedIn and authMethod are read; the email and the organization that the output brings
# never go into the detail. Without jq: the text is read with case and sed.
check_login() {
  auth_output=$(claude auth status --json 2>/dev/null)
  auth_method=$(printf '%s\n' "$auth_output" | sed -n 's/.*"authMethod": *"\([^"]*\)".*/\1/p' | sed -n 1p)
  case "$auth_output" in
    *'"loggedIn": true'*|*'"loggedIn":true'*)
      if [ -n "$auth_method" ]; then add agent-auth ok false "$(msg agentcheck.loginOkMethod "$auth_method")"; else add agent-auth ok false "$(msg agentcheck.loginOk)"; fi ;;
    *'"loggedIn": false'*|*'"loggedIn":false'*)
      add agent-auth missing false "$(msg agentcheck.noLogin)" ;;
    *)
      add agent-auth unknown false "$(msg agentcheck.authUnreadable)" ;;
  esac
}

# shellcheck disable=SC2154 # here and jq_path come from the check.sh that sources this file
check_agent() {
  plugin_name=$(sed -n 's/^ *"name": *"\([^"]*\)".*/\1/p' "$here/../.claude-plugin/plugin.json" 2>/dev/null | sed -n 1p)
  # outside a package (the adapter source) the manifest name is still the build placeholder
  case "$plugin_name" in ''|'{{'*) plugin_name=plan-relay ;; esac
  if ! cli=$(command -v claude); then
    add agent-cli missing false "$(msg agentcheck.noCli)"
    add agent-auth unknown false "$(msg agentcheck.noCliLogin)"
    add plugin unknown false "$(msg agentcheck.noCliPlugin "$plugin_name")"
    add plugin-current unknown false "$(msg agentcheck.noCliVersions)"
    return
  fi
  add agent-cli ok false "$cli"
  check_login
  if [ -z "$jq_path" ]; then
    add plugin unknown false "$(msg agentcheck.noJqList)"
    add plugin-current unknown false "$(msg agentcheck.noJqVersions)"
    return
  fi
  plugin_list=$(claude plugin list --json 2>/dev/null)
  if ! printf '%s\n' "$plugin_list" | jq -e 'type == "array"' >/dev/null 2>&1; then
    add plugin unknown false "$(msg agentcheck.listUnreadable)"
    add plugin-current unknown false "$(msg agentcheck.noListVersions)"
    return
  fi
  plugin_entry=$(printf '%s\n' "$plugin_list" | jq -c --arg n "$plugin_name@" \
    'first(.[] | select((.id // "") | startswith($n)))' 2>/dev/null)
  if [ -z "$plugin_entry" ]; then
    add plugin missing false "$(msg agentcheck.notInstalled "$plugin_name")"
    add plugin-current unknown false "$(msg agentcheck.pluginNotInstalled)"
    return
  fi
  # One field per call: the paths may have spaces.
  plugin_version=$(entry_field '.version // "?"')
  plugin_enabled=$(entry_field '.enabled != false')
  folder_version=$(entry_field '.folderVersion // ""')
  if [ "$plugin_enabled" = false ]; then add plugin warning false "$(msg agentcheck.disabled "$plugin_name" "$plugin_version")"
  else add plugin ok false "$plugin_name $plugin_version"
  fi
  if [ -z "$folder_version" ]; then
    add plugin-current unknown false "$(msg agentcheck.remoteSource "$plugin_version" "$plugin_name")"
  elif [ "$folder_version" != "$plugin_version" ]; then
    add plugin-current warning false "$(msg agentcheck.folderDiffers "$plugin_version" "$folder_version" "$plugin_name")"
  else
    check_cache
  fi
}

entry_field() { printf '%s\n' "$plugin_entry" | jq -r "$1" 2>/dev/null; }

# In a folder marketplace the CLI reads the plugin from its source (readFromFolder), but the
# VS Code Agents window reads the copy in installPath, written only at install time; with the
# same version, "plugin update" does not renew it. The file lists and the bytes of each file
# are compared.
# shellcheck disable=SC2154 # plugin_name, plugin_version and plugin_entry come from check_agent
check_cache() {
  source_dir=$(entry_field '.readFromFolder // ""')
  cache_copy=$(entry_field '.installPath // ""')
  install_scope=$(entry_field '.scope // "user"')
  if [ -z "$source_dir" ] || [ -z "$cache_copy" ]; then
    add plugin-current ok false "$(msg agentcheck.same "$plugin_version")"
    return
  fi
  same_folders "$source_dir" "$cache_copy"
  case $? in
    0) add plugin-current ok false "$(msg agentcheck.sameCache "$plugin_version")" ;;
    1) add plugin-current warning false "$(msg agentcheck.cacheDiffers "$cache_copy" "$plugin_name" "$install_scope")" ;;
    *) add plugin-current ok false "$(msg agentcheck.sameNotCompared "$plugin_version")" ;;
  esac
}

# same_folders <source> <copy>: 0 the same, 1 different, 2 no way to compare. cmp file by
# file, without diff -r, which BusyBox does not fully have.
same_folders() {
  command -v find >/dev/null 2>&1 && command -v sort >/dev/null 2>&1 && command -v cmp >/dev/null 2>&1 || return 2
  [ -d "$1" ] || return 2
  [ -d "$2" ] || return 1
  list_a=$(cd "$1" && find . -type f | LC_ALL=C sort) || return 2
  list_b=$(cd "$2" && find . -type f | LC_ALL=C sort) || return 1
  [ "$list_a" = "$list_b" ] || return 1
  printf '%s\n' "$list_a" | while IFS= read -r file; do
    cmp -s "$1/$file" "$2/$file" || exit 1
  done
}
